// Predicate evaluation, three-valued.
//
// Generated by `ess verify conform synthesize --target typescript`. Do not edit.
//
// # Why three values
//
// True, False and Unknown. The third is the point: `total.amount >= 0` is *false* when a row breaks
// the invariant and *unknown* when the row does not publish `total.amount` at all, and those need
// different responses — fix the implementation, or fix the specification or the view. A runner that
// collapsed them would report a missing field as a broken invariant.
//
// # A port, not a second opinion
//
// This file is `src/go/predicate.go` rewritten in TypeScript, function for function and message for
// message. The two runtimes are held to the same suite and must report the same counts, so a
// difference here is not a style choice; it is one specification saying two things. Where the two
// languages genuinely differ the Go behaviour wins, and the place it is reconstructed carries a
// comment saying so. There are five:
//
//   * `goTrimSpace` — Go's `strings.TrimSpace` is `unicode.IsSpace`, which holds U+0085 and not
//     U+FEFF; JavaScript's `String.prototype.trim` is the other way around.
//   * key ordering — Go's `sort.Strings` orders UTF-8 bytes, which is code point order, and
//     JavaScript's default sort orders UTF-16 code units. `sortStrings` is the runtime's, not a
//     second copy: two implementations of one ordering is the divergence this file exists to
//     rule out.
//   * `parseDecimalLiteral` — Go's `strconv.ParseFloat` reports an out-of-range exponent as an
//     error and an underflow as a signed zero; `Number` answers `Infinity` and a signed zero.
//   * `Predicate.quantify` — Go converts the count through `int`, so a count no `int64` holds is
//     Unknown rather than a loop.
//   * `quoteGo` — Go's `%q` is `strconv.Quote`, which keeps a printable rune literal;
//     `JSON.stringify` escapes a different set, and a refusal message is one text or two.
//
// One thing the Go file leaves to chance is reconstructed as a fixed order rather than a random
// one, and it is called out at `comparisonOperators`.

import {
  asNumber,
  compare,
  equal,
  exactDecimal,
  JsonNumber,
  render,
  sortStrings,
} from './runtime.js';
import type { Node, Row } from './runtime.js';

/** A three-valued result. */
export type Truth = 'true' | 'false' | 'unknown';

export const TruthTrue: Truth = 'true';
export const TruthFalse: Truth = 'false';
export const TruthUnknown: Truth = 'unknown';

// Go declares `and`, `or` and `not` as methods on a named integer type. A union of string
// literals carries no methods, so the three are functions, prefixed to keep `not` off the
// module's namespace.

export function truthAnd(left: Truth, right: Truth): Truth {
  if (left === TruthFalse || right === TruthFalse) return TruthFalse;
  if (left === TruthUnknown || right === TruthUnknown) return TruthUnknown;
  return TruthTrue;
}

export function truthOr(left: Truth, right: Truth): Truth {
  if (left === TruthTrue || right === TruthTrue) return TruthTrue;
  if (left === TruthUnknown || right === TruthUnknown) return TruthUnknown;
  return TruthFalse;
}

export function truthNot(value: Truth): Truth {
  if (value === TruthTrue) return TruthFalse;
  if (value === TruthFalse) return TruthTrue;
  return TruthUnknown;
}

export function truthOf(value: boolean): Truth {
  return value ? TruthTrue : TruthFalse;
}

/**
 * A flattened row: a scalar per dotted path.
 *
 * A collection publishes its size as `<path>.count` and its elements as `<path>.0.…`, which is what
 * a quantifier counts through. Same convention the specification half uses, so a predicate written
 * against the model evaluates here without translation.
 *
 * A mapping or a sequence binds no fact of its own, but is recorded as present in {@link presence},
 * even when it is empty: what `defined()` over an Optional struct, list or map reads
 * (beyond10x/ess#176). Beside the map rather than in it, so no value read can see it.
 *
 * A `Map` and not an object, because a fact path is arbitrary text: a row publishing
 * `constructor` or `__proto__` must be one fact, not a reader of `Object.prototype`.
 */
export type FactSource = Map<string, Node>;

/** The paths of each source that hold a mapping or a sequence; the Go runtime's `aggregatePresent`. */
const aggregates = new WeakMap<FactSource, Set<string>>();

/** The paths of `source` that hold a present mapping or sequence. */
export function presence(source: FactSource): Set<string> {
  let paths = aggregates.get(source);
  if (paths === undefined) {
    paths = new Set();
    aggregates.set(source, paths);
  }
  return paths;
}

/**
 * What `defined()` reads, the Go runtime's `present` (beyond10x/ess#176): a bound scalar, a text's
 * derived length, or a mapping or sequence — present even when empty — is present; `null` and a
 * path nothing binds are absent.
 */
export function present(source: FactSource, path: string): boolean {
  if (source.has(path)) {
    const value = source.get(path);
    return value !== null && value !== undefined;
  }
  return aggregates.get(source)?.has(path) === true || readLeaf(source, path)[1];
}

/** Flattens one row into the paths a predicate reads. */
/**
 * One leaf read, the Go runtime's `readLeaf` (beyond10x/ess#104): a bound fact wins; otherwise, when
 * the last segment is `count` and the parent is bound to text, the value is the text's number of
 * code points — `[...text].length`, which is Go's rune count for any text a JSON reader hands
 * either runtime. A quantifier's cardinality is read raw, so a quantifier over a text is Unknown.
 */
export function readLeaf(source: FactSource, path: string): [Node, boolean] {
  if (source.has(path)) return [source.get(path) ?? null, true];
  const at = path.lastIndexOf('.');
  if (at <= 0 || path.slice(at + 1) !== 'count') return [null, false];
  const parent = source.get(path.slice(0, at));
  if (typeof parent === 'string') return [[...parent].length, true];
  return [null, false];
}

/**
 * The number of bytes the UTF-8 encoding of `text` takes, or null where `text` holds a lone
 * surrogate and is no Unicode text. A JavaScript string is UTF-16 code units, so `length` counts
 * units and `[...text]` code points; `TextEncoder` writes a lone surrogate as the three bytes of
 * U+FFFD, which would measure a text nobody wrote — so well-formedness is checked first.
 */
export function utf8Length(text: string): number | null {
  for (let index = 0; index < text.length; index += 1) {
    const unit = text.charCodeAt(index);
    if (unit >= 0xdc00 && unit <= 0xdfff) return null;
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const low = text.charCodeAt(index + 1);
      if (!(low >= 0xdc00 && low <= 0xdfff)) return null;
      index += 1;
    }
  }
  return new TextEncoder().encode(text).length;
}

/**
 * The UTF-8 byte length of the text at `path`, Go's `utf8BytesOf` and Rust's `Derived::value`: a
 * bound `<path>.utf8_bytes` wins, and only a whole number from zero within `i64` is a byte length —
 * any other bound value is Unknown, with no fallback to the text. Otherwise the text at `path` is
 * measured; an unbound path, null, a value that is no text and a lone surrogate are Unknown.
 */
export function utf8BytesOf(source: FactSource, path: string): [Node, boolean] {
  const observed = `${path}.utf8_bytes`;
  const bound = source.get(observed);
  if (source.has(observed) && bound !== null && bound !== undefined) {
    const length = integerOf(bound);
    return length === null || length < 0n ? [null, false] : [bound, true];
  }
  const text = source.get(path);
  if (typeof text !== 'string') return [null, false];
  const length = utf8Length(text);
  return length === null ? [null, false] : [length, true];
}

export function facts(row: Row): FactSource {
  const flattened: FactSource = new Map();
  for (const [field, value] of Object.entries(row)) {
    bindFact(flattened, field, value);
  }
  return flattened;
}

export function bindFact(into: FactSource, path: string, value: Node): void {
  if (Array.isArray(value)) {
    // The size as well as the elements: a quantifier has no collection value to ask for a
    // length, so the length is a fact like any other.
    presence(into).add(path);
    into.set(`${path}.count`, value.length);
    for (const [index, nested] of value.entries()) {
      bindFact(into, `${path}.${index}`, nested);
    }
    return;
  }
  // A number kept as its digits is one scalar, as Go's `json.Number` is, never a mapping of its
  // `raw` field: an offset compares `i64::MAX` exactly only where the row still holds its digits.
  if (value instanceof JsonNumber) {
    into.set(path, value);
    return;
  }
  if (value !== null && typeof value === 'object') {
    presence(into).add(path);
    for (const [key, nested] of Object.entries(value)) {
      bindFact(into, `${path}.${key}`, nested);
    }
    return;
  }
  into.set(path, value);
}

// ---- the predicate ----------------------------------------------------------------------------

/**
 * One fact moved by one constant (suite/40, `docs/design/expression-family-source22.md` A2): an
 * exact integer, or elapsed seconds — Go's `offsetOperand`.
 */
export interface OffsetOperand {
  base: string;
  add: boolean;
  /** The Integer magnitude, or null for an elapsed one. */
  integer: bigint | null;
  /** The elapsed magnitude in seconds; 0 for an Integer one. */
  seconds: bigint;
  /** The magnitude as written: `5`, `24h`. */
  spelled: string;
}

/**
 * One side of a comparison: a fact to look up, a constant, one fact moved by a constant, or the
 * UTF-8 byte length of a text.
 */
export class Operand {
  path: string;
  literal: Node;
  isFact: boolean;
  offset: OffsetOperand | null;
  /**
   * The derived UTF-8 byte length of the text at `path` (suite/40,
   * `docs/design/expression-family-source22.md` decision 11): `{utf8_bytes: <path>}`. Not a fact: no
   * value is read at `path` itself, and a selection never reads one.
   */
  utf8Bytes: boolean;

  constructor(
    fields: {
      path?: string;
      literal?: Node;
      isFact?: boolean;
      offset?: OffsetOperand;
      utf8Bytes?: boolean;
    } = {},
  ) {
    this.path = fields.path ?? '';
    this.literal = fields.literal ?? null;
    this.isFact = fields.isFact ?? false;
    this.offset = fields.offset ?? null;
    this.utf8Bytes = fields.utf8Bytes ?? false;
  }

  toString(): string {
    if (this.utf8Bytes) return `{utf8_bytes: ${this.path}}`;
    if (this.offset !== null) {
      const direction = this.offset.add ? 'add' : 'subtract';
      return `{offset: {fact: ${this.offset.base}, ${direction}: ${this.offset.spelled}}}`;
    }
    return this.isFact ? this.path : render(this.literal);
  }

  resolve(source: FactSource): [Node, boolean] {
    if (this.utf8Bytes) return utf8BytesOf(source, this.path);
    if (!this.isFact) return [this.literal, true];
    return readLeaf(source, this.path);
  }
}

interface PredicateFields {
  kind?: string;
  children?: Predicate[];
  left?: Operand;
  op?: string;
  right?: Operand;
  instant?: boolean;
  path?: string;
  values?: Node[];
  over?: string;
  bind?: string;
  body?: Predicate | null;
  key?: string;
  keyKind?: string;
}

/** A condition over facts. */
export class Predicate {
  kind: string;
  children: Predicate[];
  // leaf
  left: Operand;
  op: string;
  right: Operand;
  /** A tagged comparison (`as: timestamp`, suite/40): the operands compare as instants. */
  instant: boolean;
  path: string;
  // any_of / none_of
  values: Node[];
  // quantifier
  over: string;
  bind: string;
  body: Predicate | null;
  /** distinct (suite/40): the key under `bind`, empty for the element itself, and its kind. */
  key: string;
  keyKind: string;

  constructor(fields: PredicateFields = {}) {
    this.kind = fields.kind ?? '';
    this.children = fields.children ?? [];
    this.left = fields.left ?? new Operand();
    this.op = fields.op ?? '';
    this.right = fields.right ?? new Operand();
    this.instant = fields.instant ?? false;
    this.path = fields.path ?? '';
    this.values = fields.values ?? [];
    this.over = fields.over ?? '';
    this.bind = fields.bind ?? '';
    this.body = fields.body ?? null;
    this.key = fields.key ?? '';
    this.keyKind = fields.keyKind ?? '';
  }

  toString(): string {
    switch (this.kind) {
      case 'always':
        return 'always';
      case 'never':
        return 'never';
      case 'all':
      case 'any': {
        const parts = this.children.map((child) => child.toString());
        const joiner = this.kind === 'any' ? ' or ' : ' and ';
        return `(${parts.join(joiner)})`;
      }
      case 'not':
        return `not (${this.body})`;
      case 'compare':
        return this.instant
          ? `${this.left} ${this.op} ${this.right} as timestamp`
          : `${this.left} ${this.op} ${this.right}`;
      case 'truthy':
        return this.path;
      case 'defined':
        return `defined(${this.path})`;
      case 'any_of':
      case 'none_of': {
        const parts = this.values.map((value) => render(value));
        const word = this.kind === 'none_of' ? ' not in [' : ' in [';
        return `${this.path}${word}${parts.join(', ')}]`;
      }
      case 'starts_with':
      case 'ends_with':
      case 'contains':
        return `${this.path} ${this.kind} ${render(this.values[0])}`;
      case 'equals_ignore_case':
      case 'in_ignore_case': {
        const parts = this.values.map((value) => quoteGo(String(value)));
        if (this.kind === 'equals_ignore_case' && parts.length === 1) {
          return `${this.path} ${this.kind} ${parts[0]}`;
        }
        return `${this.path} ${this.kind} [${parts.join(', ')}]`;
      }
      case 'forall':
      case 'exists':
        return `${this.kind} ${this.bind} in ${this.over}: (${this.body})`;
      case 'distinct':
        return `distinct ${this.bind} in ${this.over}${this.key === '' ? '' : ` by ${this.key}`} as ${this.keyKind}`;
      default:
        return this.kind;
    }
  }

  // ---- evaluation -----------------------------------------------------------------------------

  evaluate(source: FactSource): Truth {
    switch (this.kind) {
      case 'always':
        return TruthTrue;
      case 'never':
        return TruthFalse;
      case 'all': {
        let result = TruthTrue;
        for (const child of this.children) result = truthAnd(result, child.evaluate(source));
        return result;
      }
      case 'any': {
        let result = TruthFalse;
        for (const child of this.children) result = truthOr(result, child.evaluate(source));
        return result;
      }
      case 'not':
        return truthNot(this.body!.evaluate(source));
      case 'compare':
        return this.compare(source);
      case 'truthy': {
        const [value, ok] = readLeaf(source, this.path);
        if (!ok) return TruthUnknown;
        return truthOf(isTruthy(value));
      }
      case 'defined':
        return truthOf(present(source, this.path));
      case 'any_of':
      case 'none_of': {
        const [value, ok] = readLeaf(source, this.path);
        if (!ok) return TruthUnknown;
        const found = this.values.some((candidate) => equal(value, candidate));
        return truthOf(found === (this.kind === 'any_of'));
      }
      case 'equals_ignore_case':
      case 'in_ignore_case':
        return this.foldMatch(source);
      case 'starts_with':
      case 'ends_with':
      case 'contains':
        return this.textMatch(source);
      case 'forall':
      case 'exists':
        return this.quantify(source);
      case 'distinct':
        return this.distinct(source);
      default:
        return TruthUnknown;
    }
  }

  /**
   * A case-insensitive operator (beyond10x/ess#140): the text equals one of the literals under
   * ASCII case folding. Not `toLowerCase`, which folds Unicode; unbound or null is Unknown, and a
   * value that is not text is False.
   */
  foldMatch(source: FactSource): Truth {
    const [value, ok] = readLeaf(source, this.path);
    if (!ok || value === null || value === undefined) return TruthUnknown;
    if (typeof value !== 'string') return TruthFalse;
    return truthOf(
      this.values.some((literal) => typeof literal === 'string' && asciiEqualFold(value, literal)),
    );
  }

  /**
   * A string operator (beyond10x/ess#95): the text begins with, ends with or contains the literal,
   * case-sensitively and with no normalisation — `TextOp::holds` in Rust. Code-unit matching agrees
   * with byte matching for any two well-formed strings. Unbound is Unknown, as for the fold above;
   * a value or a literal that is not text is False.
   */
  textMatch(source: FactSource): Truth {
    const [value, ok] = readLeaf(source, this.path);
    if (!ok || value === null || value === undefined) return TruthUnknown;
    const literal = this.values[0];
    if (typeof value !== 'string' || typeof literal !== 'string') return TruthFalse;
    switch (this.kind) {
      case 'starts_with':
        return truthOf(value.startsWith(literal));
      case 'ends_with':
        return truthOf(value.endsWith(literal));
      default:
        return truthOf(value.includes(literal));
    }
  }

  /** The Go method of the same name; `compare` below it is the runtime's ordering function. */
  compare(source: FactSource): Truth {
    if (this.right.offset !== null) return this.compareOffset(source, this.right.offset);
    const [left, leftOk] = this.left.resolve(source);
    const [right, rightOk] = this.right.resolve(source);
    if (!leftOk || !rightOk) return TruthUnknown;
    if (this.instant) {
      // Decision 2: the instants the two operands name, under every operator. A text that names
      // no instant is Unknown, never ordered by its spelling.
      const a = typeof left === 'string' ? parseInstant(left) : undefined;
      const b = typeof right === 'string' ? parseInstant(right) : undefined;
      if (a === undefined || b === undefined) return TruthUnknown;
      return truthOf(acceptsOrder(this.op, compareInstants(a, b)));
    }
    if (this.op === '==' || this.op === '!=') {
      return truthOf(equal(left, right) === (this.op === '=='));
    }
    const [order, ok] = compare(left, right);
    if (!ok) return TruthUnknown;
    switch (this.op) {
      case '<':
        return truthOf(order < 0);
      case '<=':
        return truthOf(order <= 0);
      case '>':
        return truthOf(order > 0);
      case '>=':
        return truthOf(order >= 0);
      default:
        return TruthUnknown;
    }
  }

  /**
   * `left <op> base ± magnitude` (A2), as Go's `compareOffset`: an Integer magnitude compares two
   * whole numbers with the exact sum, as `bigint`, so nothing wraps, saturates or rounds; an elapsed
   * one moves the base instant by seconds and compares instants. An unread value, a value of the
   * wrong kind, or a moved instant past what a `date-time` spells is Unknown.
   */
  compareOffset(source: FactSource, offset: OffsetOperand): Truth {
    const [left, leftOk] = this.left.resolve(source);
    const [base, baseOk] = readLeaf(source, offset.base);
    if (!leftOk || !baseOk) return TruthUnknown;
    if (offset.integer !== null) {
      const a = integerOf(left);
      const b = integerOf(base);
      if (a === null || b === null) return TruthUnknown;
      const bound = offset.add ? b + offset.integer : b - offset.integer;
      return truthOf(acceptsOrder(this.op, a < bound ? -1 : a > bound ? 1 : 0));
    }
    const a = typeof left === 'string' ? parseInstant(left) : undefined;
    const b = typeof base === 'string' ? parseInstant(base) : undefined;
    if (a === undefined || b === undefined) return TruthUnknown;
    const moved = {
      seconds: b.seconds + (offset.add ? offset.seconds : -offset.seconds),
      nanos: b.nanos,
    };
    if (moved.seconds < FIRST_SPELLED_SECOND || moved.seconds > LAST_SPELLED_SECOND) {
      return TruthUnknown;
    }
    return truthOf(acceptsOrder(this.op, compareInstants(a, moved)));
  }

  /**
   * Walks the collection, rebinding the body's reads onto each element.
   *
   * An unobserved collection is Unknown, never the vacuous truth an empty one gives: *nobody
   * looked* and *there was nothing to look at* are the two situations three-valued logic exists to
   * separate.
   */
  quantify(source: FactSource): Truth {
    const key = `${this.over}.count`;
    if (!source.has(key)) return TruthUnknown;
    const [count, ok] = asNumber(source.get(key) ?? null);
    // Go writes `count != float64(int(count))`, which is also how it refuses a count no `int`
    // holds: on a 64-bit target the conversion saturates and the round trip fails. NaN, both
    // infinities and anything from 2^63 up are Unknown in both runtimes for that reason.
    if (
      !ok ||
      count < 0 ||
      !Number.isFinite(count) ||
      count !== Math.trunc(count) ||
      count >= 2 ** 63
    ) {
      return TruthUnknown;
    }

    const universal = this.kind === 'forall';
    let result = universal ? TruthTrue : TruthFalse;
    for (let index = 0; index < count; index += 1) {
      const element = rebind(source, this.bind, `${this.over}.${index}`);
      const got = this.body!.evaluate(element);
      if (universal) {
        result = truthAnd(result, got);
        if (result === TruthFalse) break;
      } else {
        result = truthOr(result, got);
        if (result === TruthTrue) break;
      }
    }
    return result;
  }

  /**
   * `distinct: {in, as, by, kind}` (suite/40), Go's `distinct` and Rust's `Distinct::evaluate`: a
   * present empty or one-element list holds; for more, two known equal keys anywhere make it false,
   * every key known and pairwise unequal makes it true, and anything else is unknown. An absent list
   * is unknown, not empty, and an absent key is neither skipped nor one shared null.
   */
  distinct(source: FactSource): Truth {
    const counted = `${this.over}.count`;
    if (!source.has(counted)) return TruthUnknown;
    const [count, ok] = asNumber(source.get(counted) ?? null);
    if (
      !ok ||
      count < 0 ||
      !Number.isFinite(count) ||
      count !== Math.trunc(count) ||
      count >= 2 ** 63
    ) {
      return TruthUnknown;
    }
    if (count < 2) return TruthTrue;
    const key = this.key === '' ? this.bind : this.key;
    const seen = new Set<string>();
    let unknown = false;
    for (let index = 0; index < count; index += 1) {
      const element = rebind(source, this.bind, `${this.over}.${index}`);
      const [value, read] = readLeaf(element, key);
      const spelled =
        read && value !== null && value !== undefined ? distinctKey(this.keyKind, value) : null;
      if (spelled === null) {
        unknown = true;
        continue;
      }
      if (seen.has(spelled)) return TruthFalse;
      seen.add(spelled);
    }
    return unknown ? TruthUnknown : TruthTrue;
  }
}

/**
 * The source seen from inside one element: reads of `<bind>.rest` become reads of `<prefix>.rest`,
 * and every other path passes through. A root of the same name as `bind`, and everything under it,
 * is out of sight, as Rust's `Element::rebind` hides it and Go's `rebind` does: an element without
 * the member read is Unknown, never the root field's value.
 */
export function rebind(source: FactSource, bind: string, prefix: string): FactSource {
  const outer = (path: string): boolean => path === bind || path.startsWith(`${bind}.`);
  const bound: FactSource = new Map([...source].filter(([path]) => !outer(path)));
  for (const [path, value] of source) {
    if (path === prefix) {
      bound.set(bind, value);
      continue;
    }
    if (path.startsWith(`${prefix}.`)) {
      bound.set(`${bind}.${path.slice(prefix.length + 1)}`, value);
    }
  }
  const held = aggregates.get(source);
  if (held !== undefined) {
    const rebound = presence(bound);
    for (const path of held) {
      if (!outer(path)) rebound.add(path);
      if (path === prefix) rebound.add(bind);
      else if (path.startsWith(`${prefix}.`))
        rebound.add(`${bind}.${path.slice(prefix.length + 1)}`);
    }
  }
  return bound;
}

export function isTruthy(value: Node): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') return value !== '';
  if (value === null) return false;
  const [number, ok] = asNumber(value);
  if (ok) return number !== 0;
  return true;
}

// ---- parsing ------------------------------------------------------------------------------------

/**
 * Reads a predicate out of the suite.
 *
 * Go takes the undecoded `json.RawMessage` and decodes it here; a TypeScript runner has already
 * decoded the suite with `JSON.parse`, so this takes the decoded node. An expectation carrying no
 * predicate at all arrives as `undefined`, which is Go's empty raw message; an explicit JSON
 * `null` arrives as `null`, which is Go's decoded `nil`, and the two are refused differently for
 * the same reason they are in Go.
 */
export function parsePredicate(raw: Node | undefined): Predicate {
  if (raw === undefined) throw new Error('no predicate is written');
  return fromNode(raw);
}

export function fromNode(node: Node | undefined, binders: readonly string[] = []): Predicate {
  if (typeof node === 'boolean') {
    return new Predicate({ kind: node ? 'always' : 'never' });
  }
  if (typeof node === 'string') {
    return parseLeaf(node, binders);
  }
  if (Array.isArray(node)) {
    return new Predicate({ kind: 'all', children: fromNodes(node, binders) });
  }
  if (node !== null && node !== undefined && typeof node === 'object') {
    // Sorted, so a mapping with more than one entry parses the same way twice. Go randomises
    // map iteration, and a predicate that reordered between runs would make a failure report
    // unreadable across two of them.
    const keys = sortStrings(Object.keys(node));
    const children = keys.map((key) => fromEntry(key, node[key] ?? null, binders));
    if (children.length === 1) return children[0]!;
    return new Predicate({ kind: 'all', children });
  }
  throw new Error(`a predicate is an expression, a list or a mapping, not ${goTypeName(node)}`);
}

export function fromNodes(nodes: Node[], binders: readonly string[] = []): Predicate[] {
  return nodes.map((node) => fromNode(node, binders));
}

export function fromEntry(key: string, value: Node, binders: readonly string[] = []): Predicate {
  switch (key) {
    case 'distinct':
      // `as` is no operator, so a mapping holding it was never a constraint on a fact named
      // `distinct`, as Rust's `from_entry` reads it.
      if (isFactMapping(value) && Object.hasOwn(value, 'as')) {
        return parseDistinct(value);
      }
      return parseConstraint(key, value, binders);
    case 'all':
    case 'and':
    case 'all_of':
    case 'any':
    case 'or': {
      const items = Array.isArray(value) ? value : [value];
      const children = fromNodes(items, binders);
      const kind = key === 'any' || key === 'or' ? 'any' : 'all';
      return new Predicate({ kind, children });
    }
    case 'not':
      return new Predicate({ kind: 'not', body: fromNode(value, binders) });
    case 'forall':
    case 'exists':
      return parseQuantifier(key, value, binders);
    case 'compare':
      if (isFactMapping(value) && Object.hasOwn(value, 'left')) {
        return parseTaggedCompare(value, binders);
      }
      return parseConstraint(key, value, binders);
    default:
      return parseConstraint(key, value, binders);
  }
}

/**
 * Reads the closed `{compare: …}` form of a comparison (suite/40,
 * `docs/design/expression-family-source22.md`), as Rust's `Predicate::tagged_compare` does: tagged
 * to compare instants (decision 2), `{compare: {left, op, right, as: timestamp}}`, or untagged with
 * a derived operand (decision 11), `{compare: {left: {utf8_bytes: <path>}, op, right}}` — exactly
 * those keys. `as` never stands beside a derived operand, and the untagged form carries one. A
 * mapping under `compare` without `left` is a constraint on a fact named `compare`, as it always was.
 */
export function parseTaggedCompare(
  fields: { [key: string]: Node },
  binders: readonly string[] = [],
): Predicate {
  const refuse = (reason: string): never => {
    throw new Error(`compare: ${reason}`);
  };
  const tagged = Object.hasOwn(fields, 'as');
  if (
    Object.keys(fields).length !== (tagged ? 4 : 3) ||
    !Object.hasOwn(fields, 'op') ||
    !Object.hasOwn(fields, 'right')
  ) {
    refuse(
      'a `{compare: …}` comparison takes exactly `left`, `op` and `right`, and `as` where it is tagged',
    );
  }
  const written = fields['left'] ?? null;
  let left: Operand;
  if (typeof written === 'string' && factPath.test(written)) {
    left = new Operand({ path: written, isFact: true });
  } else if (
    isFactMapping(written) &&
    Object.keys(written).length === 1 &&
    Object.hasOwn(written, 'utf8_bytes')
  ) {
    left = parseUtf8BytesOperand('compare', 'left', written['utf8_bytes'] ?? null);
  } else {
    return refuse('`left` names a fact path or `{utf8_bytes: <path>}`');
  }
  const spelled = fields['op'];
  const op =
    typeof spelled === 'string'
      ? comparisonOperators.find(([spelling]) => spelling === spelled)?.[1]
      : undefined;
  if (op === undefined) refuse('`op` is one of eq, ne, lt, lte, gt, gte');
  if (tagged && fields['as'] !== 'timestamp') {
    refuse('`as` names the one kind a comparison is tagged with, `timestamp`');
  }
  const compared = fields['right'] ?? null;
  let right: Operand;
  if (typeof compared === 'string') {
    right = parseOperand(compared, binders);
  } else if (isFactMapping(compared) && !(compared instanceof JsonNumber)) {
    right = parseMappingOperand('compare', 'right', compared);
  } else if (compared === null || Array.isArray(compared)) {
    return refuse('`right` is a scalar or `{fact: <path>}`');
  } else {
    right = new Operand({ literal: compared });
  }
  const derived = left.utf8Bytes || right.utf8Bytes;
  if (!tagged) {
    if (!derived) {
      refuse(
        'an untagged `{compare: …}` carries a derived operand, `{utf8_bytes: <path>}`; compare two facts as `<path>: {<op>: …}`',
      );
    }
    return new Predicate({ kind: 'compare', left, op: op as string, right });
  }
  if (derived) refuse('a derived operand compares as a number, never `as: timestamp`');
  return new Predicate({
    kind: 'compare',
    left,
    op: op as string,
    right,
    instant: true,
  });
}

/** Applies a comparison operator to an ordering, as Rust's `CompareOp::accepts` does. */
function acceptsOrder(op: string, order: number): boolean {
  switch (op) {
    case '==':
      return order === 0;
    case '!=':
      return order !== 0;
    case '<':
      return order < 0;
    case '<=':
      return order <= 0;
    case '>':
      return order > 0;
    default:
      return order >= 0;
  }
}

/** `0000-01-01T00:00:00Z` and `9999-12-31T23:59:59Z`: the seconds a `date-time` spells. */
const FIRST_SPELLED_SECOND = -62167219200n;
const LAST_SPELLED_SECOND = 253402300799n;

/** An Integer value: a number whose exact value is a whole number within `i64`, or null. */
function integerOf(value: Node): bigint | null {
  const decimal = exactDecimal(value);
  if (decimal === null || decimal[1] !== 0) return null;
  const [units] = decimal;
  return units > 9223372036854775807n || units < -9223372036854775808n ? null : units;
}

/** One RFC 3339 `date-time` on the UTC line: seconds since the epoch and nanoseconds. */
export interface Instant {
  seconds: bigint;
  nanos: number;
}

export function compareInstants(a: Instant, b: Instant): number {
  if (a.seconds !== b.seconds) return a.seconds < b.seconds ? -1 : 1;
  if (a.nanos !== b.nanos) return a.nanos < b.nanos ? -1 : 1;
  return 0;
}

/**
 * Rust's `Rfc3339Instant::parse_rfc3339` (decision 14): the `date-time` production and nothing
 * wider — `T` or `t`, seconds 00–59 (no leap second), up to nine fraction digits, and `Z`, `z` or
 * a `±HH:MM` offset; years 0000–9999 with real month lengths. The vectors it answers are
 * `crates/specify/ess-primitives/tests/vectors/rfc3339-instants.json`.
 */
export function parseInstant(text: string): Instant | undefined {
  const digits = (from: number, to: number): number | undefined => {
    if (from >= to || to > text.length) return undefined;
    let total = 0;
    for (let index = from; index < to; index += 1) {
      const code = text.charCodeAt(index);
      if (code < 48 || code > 57) return undefined;
      total = total * 10 + (code - 48);
    }
    return total;
  };
  const at = (index: number, expected: string): boolean =>
    index < text.length && expected.includes(text[index]!);
  if (!(at(4, '-') && at(7, '-') && at(10, 'Tt') && at(13, ':') && at(16, ':'))) return undefined;
  const year = digits(0, 4);
  const month = digits(5, 7);
  const day = digits(8, 10);
  const hour = digits(11, 13);
  const minute = digits(14, 16);
  const second = digits(17, 19);
  if (
    year === undefined ||
    month === undefined ||
    day === undefined ||
    hour === undefined ||
    minute === undefined ||
    second === undefined ||
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > daysInMonth(year, month) ||
    hour > 23 ||
    minute > 59 ||
    second > 59
  ) {
    return undefined;
  }
  let position = 19;
  let nanos = 0;
  if (at(position, '.')) {
    let end = position + 1;
    while (end < text.length && text.charCodeAt(end) >= 48 && text.charCodeAt(end) <= 57) end += 1;
    const width = end - position - 1;
    if (width === 0 || width > 9) return undefined;
    nanos = digits(position + 1, end)! * 10 ** (9 - width);
    position = end;
  }
  const rest = text.slice(position);
  let offset = 0;
  if (rest !== 'Z' && rest !== 'z') {
    if (rest.length !== 6 || (rest[0] !== '+' && rest[0] !== '-') || rest[3] !== ':') {
      return undefined;
    }
    const hours = digits(position + 1, position + 3);
    const minutes = digits(position + 4, position + 6);
    if (hours === undefined || minutes === undefined || hours > 23 || minutes > 59) {
      return undefined;
    }
    offset = (hours * 3600 + minutes * 60) * (rest[0] === '-' ? -1 : 1);
  }
  const seconds =
    daysFromCivil(year, month, day) * 86400n + BigInt(hour * 3600 + minute * 60 + second - offset);
  return { seconds, nanos };
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0 ? 29 : 28;
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

/** Days from 1970-01-01 to a proleptic Gregorian date. */
function daysFromCivil(year: number, month: number, day: number): bigint {
  const y = month <= 2 ? year - 1 : year;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const shifted = month > 2 ? month - 3 : month + 9;
  const doy = Math.floor((153 * shifted + 2) / 5) + day - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return BigInt(era * 146097 + doe - 719468);
}

/** The key kinds a `distinct` names, Rust's `DistinctKeyKind`. */
export const DISTINCT_KINDS = [
  'boolean',
  'integer',
  'decimal',
  'string',
  'uuid',
  'timestamp',
  'enum',
] as const;

/**
 * Reads `{distinct: {in, as, by, kind}}` (suite/40, `docs/design/expression-family-source22.md`
 * `distinct`), Go's `parseDistinct`, and requires `kind`: a suite never carries a key whose
 * equality its reader would have to infer.
 */
export function parseDistinct(fields: { [key: string]: Node }): Predicate {
  for (const field of Object.keys(fields)) {
    if (!['in', 'as', 'by', 'kind'].includes(field)) {
      throw new Error(
        `distinct: \`${field}\`: \`distinct\` takes \`in\`, \`as\`, \`by\` and \`kind\`, and nothing else`,
      );
    }
  }
  const over = fields['in'];
  if (typeof over !== 'string' || !factPath.test(over)) {
    throw new Error('distinct: `in` names the list, a fact path');
  }
  const bind = fields['as'];
  if (typeof bind !== 'string' || !factPath.test(bind) || bind.includes('.')) {
    throw new Error('distinct: `as` names each element, one fact path segment');
  }
  let key = '';
  if (Object.hasOwn(fields, 'by')) {
    const by = fields['by'];
    if (typeof by !== 'string' || !factPath.test(by) || !by.startsWith(`${bind}.`)) {
      throw new Error(`distinct: \`by\` names one member under the binder \`${bind}\``);
    }
    key = by;
  }
  const kind = fields['kind'];
  if (typeof kind !== 'string' || !(DISTINCT_KINDS as readonly string[]).includes(kind)) {
    throw new Error(
      'distinct: `kind` names the key kind: boolean, integer, decimal, string, uuid, timestamp or enum',
    );
  }
  return new Predicate({ kind: 'distinct', over, bind, key, keyKind: kind });
}

/**
 * A value spelled under its key kind so equal keys spell alike — exact numbers, the instant of a
 * timestamp, exact text — or null where the value lies outside the kind. Go's `distinctKey`.
 */
export function distinctKey(kind: string, value: Node): string | null {
  switch (kind) {
    case 'boolean':
      return typeof value === 'boolean' ? String(value) : null;
    case 'integer': {
      const integer = integerOf(value);
      return integer === null ? null : integer.toString();
    }
    case 'decimal': {
      const decimal = exactDecimal(value);
      return decimal === null ? null : `${decimal[0]}e-${decimal[1]}`;
    }
    case 'string':
    case 'uuid':
    case 'enum':
      return typeof value === 'string' ? value : null;
    case 'timestamp': {
      if (typeof value !== 'string') return null;
      const at = parseInstant(value);
      return at === undefined ? null : `${at.seconds}.${at.nanos}`;
    }
    default:
      return null;
  }
}

export function parseQuantifier(
  kind: string,
  value: Node,
  binders: readonly string[] = [],
): Predicate {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error('a quantifier is a mapping with `in`, `as` and `that`');
  }
  const over = typeof value['in'] === 'string' ? value['in'] : '';
  const bind = typeof value['as'] === 'string' ? value['as'] : '';
  if (over === '' || bind === '') {
    throw new Error('a quantifier needs both `in` and `as`');
  }
  return new Predicate({ kind, over, bind, body: fromNode(value['that'], [...binders, bind]) });
}

// Go ranges a map literal here, so which operator a constraint carrying two of them is read as is
// randomised per run. An object preserves insertion order, so this list is that choice made once:
// the first spelling present wins, in the order Go writes them. A single-operator constraint —
// every one a synthesized suite carries — parses identically either way.
/** The string operators of suite/14, one spelling each (beyond10x/ess#95). */
export const TEXT_OPERATORS = ['starts_with', 'ends_with', 'contains'] as const;

const comparisonOperators: [string, string][] = [
  ['eq', '=='],
  ['equals', '=='],
  ['==', '=='],
  ['ne', '!='],
  ['not_equals', '!='],
  ['!=', '!='],
  ['lt', '<'],
  ['<', '<'],
  ['le', '<='],
  ['lte', '<='],
  ['<=', '<='],
  ['gt', '>'],
  ['>', '>'],
  ['ge', '>='],
  ['gte', '>='],
  ['>=', '>='],
];

export function parseConstraint(
  path: string,
  value: Node,
  binders: readonly string[] = [],
): Predicate {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return new Predicate({
      kind: 'compare',
      left: new Operand({ path, isFact: true }),
      op: '==',
      right: new Operand({ literal: value }),
    });
  }
  for (const key of ['any_of', 'none_of']) {
    if (Object.hasOwn(value, key)) {
      const listed = value[key];
      if (!Array.isArray(listed)) throw new Error(`\`${key}\` takes a list`);
      return new Predicate({ kind: key, path, values: listed });
    }
  }
  // The string operators (beyond10x/ess#95, suite/14): one literal, read verbatim — `"+44"` stays
  // text and `"a.b"` is no fact path — and kept whatever its type, so a number never matches.
  for (const key of TEXT_OPERATORS) {
    if (Object.hasOwn(value, key)) {
      return new Predicate({ kind: key, path, values: [value[key] ?? null] });
    }
  }
  // The case-insensitive operators (beyond10x/ess#140), operands verbatim as Go reads them.
  if (Object.hasOwn(value, 'equals_ignore_case')) {
    const literal = value['equals_ignore_case'];
    if (typeof literal !== 'string') {
      throw new Error(`\`${path}: {equals_ignore_case: …}\` takes a string`);
    }
    return new Predicate({ kind: 'equals_ignore_case', path, values: [literal] });
  }
  if (Object.hasOwn(value, 'in_ignore_case')) {
    const listed = value['in_ignore_case'];
    if (!Array.isArray(listed) || !listed.every((item) => typeof item === 'string')) {
      throw new Error(`\`${path}: {in_ignore_case: …}\` takes a list of strings`);
    }
    return new Predicate({ kind: 'in_ignore_case', path, values: listed });
  }
  for (const [spelling, op] of comparisonOperators) {
    if (Object.hasOwn(value, spelling)) {
      const compared = value[spelling] ?? null;
      const right =
        typeof compared === 'string'
          ? parseOperand(compared, binders)
          : isFactMapping(compared)
            ? parseMappingOperand(path, spelling, compared)
            : new Operand({ literal: compared });
      return new Predicate({
        kind: 'compare',
        left: new Operand({ path, isFact: true }),
        op,
        right,
      });
    }
  }
  throw new Error(`\`${path}\` carries no operator this runner knows`);
}

/** Whether `value` is a mapping, which a comparison operand can only be as `{fact: <path>}`. */
function isFactMapping(value: Node): value is { [key: string]: Node } {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Reads the explicit fact operand `{fact: <path>}`, the canonical spelling of a one-segment fact on
 * the right of a comparison (suite/40, `docs/design/expression-family-source22.md` A1), as Rust's
 * `Operand::fact_mapping` does: exactly one key, naming a fact path. Anything else is refused
 * rather than compared as the mapping it is. Which suite majors may carry it is the runtime's
 * admission to decide; this reader only reads it.
 */
function parseMappingOperand(path: string, key: string, value: { [key: string]: Node }): Operand {
  if (Object.keys(value).length === 1 && Object.hasOwn(value, 'offset')) {
    return parseOffsetOperand(path, key, value['offset'] ?? null);
  }
  if (Object.keys(value).length === 1 && Object.hasOwn(value, 'utf8_bytes')) {
    return parseUtf8BytesOperand(path, key, value['utf8_bytes'] ?? null);
  }
  return parseFactOperand(path, key, value);
}

/**
 * Reads the derived UTF-8 byte length of a text, `{utf8_bytes: <path>}` (suite/40,
 * `docs/design/expression-family-source22.md` decision 11), as Rust's `Operand::fact_mapping` does:
 * one key, naming a fact path. Which suite majors may carry it is the runtime's admission to decide.
 */
export function parseUtf8BytesOperand(path: string, key: string, value: Node): Operand {
  if (typeof value !== 'string' || !factPath.test(value)) {
    throw new Error(`\`${path}: {${key}: {utf8_bytes: …}}\` names the fact path of a text`);
  }
  return new Operand({ path: value, utf8Bytes: true });
}

/**
 * Reads one constant offset, `{offset: {fact: <path>, add|subtract: <magnitude>}}` (suite/40, A2),
 * as Rust's `OffsetOperand::from_entries` does: exactly `fact` and one of `add` and `subtract`; a
 * number that is a whole number from 0 to `i64::MAX`, or a text `<digits><s|m|h>` without a leading
 * zero under the current-time bound. A whole number written as text is refused.
 */
function parseOffsetOperand(path: string, key: string, value: Node): Operand {
  const refuse = (): never => {
    throw new Error(
      `\`${path}: {${key}: {offset: …}}\` takes exactly \`fact\`, a fact path, and one of \`add\` and \`subtract\``,
    );
  };
  if (
    value === null ||
    typeof value !== 'object' ||
    Array.isArray(value) ||
    value instanceof JsonNumber
  ) {
    return refuse();
  }
  const fields = value as { [key: string]: Node };
  const base = fields['fact'];
  const add = Object.hasOwn(fields, 'add');
  const direction = add ? 'add' : 'subtract';
  if (
    Object.keys(fields).length !== 2 ||
    typeof base !== 'string' ||
    !factPath.test(base) ||
    add === Object.hasOwn(fields, 'subtract')
  ) {
    return refuse();
  }
  const magnitude = fields[direction] ?? null;
  if (typeof magnitude === 'string') {
    const matched = /^([1-9][0-9]{0,9}|0)([smh])$/.exec(magnitude);
    if (matched === null) return refuse();
    const unit = { s: 1n, m: 60n, h: 3600n }[matched[2] as 's' | 'm' | 'h'];
    const seconds = BigInt(matched[1]!) * unit;
    if (seconds > 3155760000n) return refuse();
    return new Operand({
      offset: { base, add, integer: null, seconds, spelled: magnitude },
    });
  }
  const integer = integerOf(magnitude);
  if (integer === null || integer < 0n || typeof magnitude === 'boolean') return refuse();
  return new Operand({
    offset: { base, add, integer, seconds: 0n, spelled: integer.toString() },
  });
}

function parseFactOperand(path: string, key: string, value: { [key: string]: Node }): Operand {
  const fact = value['fact'];
  if (Object.keys(value).length !== 1 || typeof fact !== 'string' || !factPath.test(fact)) {
    throw new Error(
      `\`${path}: {${key}: …}\`: a comparison operand must be a scalar, or \`{fact: <path>}\` naming a fact`,
    );
  }
  return new Operand({ path: fact, isFact: true });
}

/** Reads compact expressions. Unrepresentable literal data uses structured comparisons. */
export function parseLeaf(expression: string, binders: readonly string[] = []): Predicate {
  admitPredicateExpression(expression, 0);
  const trimmed = goTrimSpace(expression);
  if (trimmed.startsWith('not ')) {
    return new Predicate({ kind: 'not', body: parseLeaf(trimmed.slice('not '.length), binders) });
  }
  if (trimmed === 'always') return new Predicate({ kind: 'always' });
  if (trimmed === 'never') return new Predicate({ kind: 'never' });
  if (trimmed.startsWith('defined(')) {
    const rest = trimmed.slice('defined('.length);
    if (!rest.endsWith(')')) {
      throw new Error(`\`${trimmed}\` opens \`defined(\` and does not close it`);
    }
    return new Predicate({ kind: 'defined', path: goTrimSpace(rest.slice(0, -1)) });
  }
  const [left, op, right, split] = splitPredicateComparison(trimmed);
  if (split) {
    return new Predicate({
      kind: 'compare',
      // The left-hand side of a comparison is always a fact path, never a literal —
      // which is what `Predicate::parse_expression` does on the Rust side, and the two
      // have to agree or the same specification says different things to two runners.
      // Read as a literal instead, `reschedule_count >= 0` compares the *word* to zero
      // and `state == Bridged` compares two words, which is false and silently vacuous
      // under the `not` an implication is written with.
      left: new Operand({ path: goTrimSpace(left), isFact: true }),
      op,
      right: parseOperand(right, binders),
    });
  }
  if (/[ ()[\]]/.test(trimmed)) {
    throw new Error(`\`${trimmed}\` is an expression this generated runner does not implement`);
  }
  return new Predicate({ kind: 'truthy', path: trimmed });
}

/**
 * Reads the right-hand side of a comparison.
 *
 * A bare word containing a dot is a fact path and anything else is a literal, which is the model's
 * own rule; a literal containing dots is quoted. Inside a quantifier body, an unquoted word that is
 * exactly the name of a binder in scope reads that binder (beyond10x/ess#289), as Rust's
 * `Operand::parse_in` does; quoted, it is the text.
 */
export function parseOperand(raw: string, binders: readonly string[] = []): Operand {
  const trimmed = goTrimSpace(raw);
  const quoted = trimmed.startsWith('"') || trimmed.startsWith("'");
  if (!quoted && factPath.test(trimmed) && binders.includes(trimmed)) {
    return new Operand({ path: trimmed, isFact: true });
  }
  if (!quoted && trimmed.includes('.')) {
    const [, numeric] = parseDecimalLiteral(trimmed);
    if (!numeric && factPath.test(trimmed)) {
      return new Operand({ path: trimmed, isFact: true });
    }
  }
  return new Operand({ literal: parseLiteral(trimmed) });
}

export function parseLiteral(raw: string): Node {
  if (raw.length >= 2) {
    for (const quote of ['"', "'"]) {
      if (raw.startsWith(quote) && raw.endsWith(quote)) {
        return raw.slice(1, -1);
      }
    }
  }
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  const [number, ok] = parseDecimalLiteral(raw);
  if (ok) return number;
  return raw;
}

/**
 * Rust `Number::parse_decimal` admits finite decimal f64 literals. Go's `strconv` also accepts
 * NaN, infinities, hexadecimal floats and underscores; those spellings remain text in predicates,
 * which the grammar below is what refuses. What `strconv.ParseFloat` then reports as out of range
 * — an overflowing exponent — `Number` answers as an infinity, so finiteness is the test. An
 * underflow is a signed zero and an accepted number in both.
 */
export function parseDecimalLiteral(raw: string): [number, boolean] {
  if (!meaningDecimal.test(raw)) return [0, false];
  const number = Number(raw);
  if (!Number.isFinite(number)) return [0, false];
  return [number, true];
}

// ---- admission --------------------------------------------------------------------------------

// Compact string leaves are the only envelope shape this file reads; the runtime admits the
// structured shapes, which need its reader. Both spend the same Rust depth budget, and the
// definitions below stay here so this file depends on nothing the runtime declares.
//
// Go reports a refusal as an `error`; here it is a thrown `Error` carrying the same message, so
// the reason a report quotes is the same text in both runtimes.
export function admitPredicateExpression(expression: string, depth = 0): void {
  if (depth > 32) throw new Error('predicate exceeds maximum depth 32');
  const trimmed = goTrimSpace(expression);
  if (trimmed.startsWith('not ')) {
    admitPredicateExpression(trimmed.slice('not '.length), depth + 1);
    return;
  }
  admitPredicateLeaf(expression);
}

export function admitPredicatePath(path: string): void {
  if (!factPath.test(path)) throw new Error(`invalid predicate fact path ${quoteGo(path)}`);
}

export function admitPredicateLeaf(expression: string): void {
  const trimmed = goTrimSpace(expression);
  switch (trimmed) {
    case 'always':
    case 'true':
    case 'never':
    case 'false':
      return;
    default:
      break;
  }
  for (const functionName of ['defined', 'exists', 'missing']) {
    if (!trimmed.startsWith(functionName)) continue;
    const opened = goTrimSpace(trimmed.slice(functionName.length));
    if (!opened.startsWith('(')) continue;
    const closed = goTrimSpace(opened.slice(1));
    if (!closed.endsWith(')')) continue;
    admitPredicatePath(goTrimSpace(closed.slice(0, -1)));
    return;
  }
  const [left, , right, split] = splitPredicateComparison(trimmed);
  if (split) {
    admitPredicatePath(goTrimSpace(left));
    if (goTrimSpace(right) === '') {
      throw new Error('predicate comparison requires a right operand');
    }
    admitQuotedOperand(right);
    return;
  }
  admitPredicatePath(trimmed);
}

/**
 * Quoting delimits one compact operand. Escape bytes retain their historical literal value;
 * they only prevent an escaped quote from ending the operand. Structured scalar data is separate.
 */
export function admitQuotedOperand(raw: string): void {
  const trimmed = goTrimSpace(raw);
  if (trimmed === '' || (trimmed[0] !== '"' && trimmed[0] !== "'")) return;
  const quote = trimmed[0];
  let escaped = false;
  for (let index = 1; index < trimmed.length; index += 1) {
    const character = trimmed[index];
    if (escaped) {
      escaped = false;
    } else if (character === '\\') {
      escaped = true;
    } else if (character === quote) {
      if (goTrimSpace(trimmed.slice(index + 1)) !== '') {
        throw new Error(
          'tokens after a quoted operand are unsupported; use structured any/all/not',
        );
      }
      return;
    }
  }
  throw new Error(
    'quoted operand is not closed; close the quote and use structured any/all/not to combine predicates',
  );
}

/**
 * Rust `split_comparison` chooses the first operator outside quotes, examining two-byte
 * operators before one-byte operators at that position. Admission and evaluation share the split.
 *
 * Go walks bytes and this walks UTF-16 code units. Every byte and every unit either side of an
 * ASCII operator is outside the ASCII range, so the two find the same operator at the same place
 * and cut the same three substrings.
 */
export function splitPredicateComparison(trimmed: string): [string, string, string, boolean] {
  let quote = '';
  for (let index = 0; index < trimmed.length; index += 1) {
    const character = trimmed[index]!;
    if (quote !== '') {
      if (character === quote) quote = '';
      continue;
    }
    if (character === "'" || character === '"') {
      quote = character;
      continue;
    }
    let width = 0;
    if (index + 1 < trimmed.length) {
      const pair = trimmed.slice(index, index + 2);
      if (pair === '==' || pair === '!=' || pair === '<=' || pair === '>=') width = 2;
    }
    if (width === 0 && (character === '<' || character === '>')) width = 1;
    if (width !== 0) {
      return [
        trimmed.slice(0, index),
        trimmed.slice(index, index + width),
        trimmed.slice(index + width),
        true,
      ];
    }
  }
  return ['', '', '', false];
}

export const meaningDecimal = /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$/;

export const factPath = /^_*[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+)*$/;

// ---- the four places the two languages do not agree by themselves ------------------------------

// Go `unicode.IsSpace`, which `strings.TrimSpace` uses. JavaScript's `String.prototype.trim`
// holds U+FEFF, which Go does not, and omits U+0085, which Go has — so a leaf led by a NEL would
// keep it in its fact path here and lose it in Go, and a leaf led by a BOM the other way. The
// browser adapter reconstructs the same class for the same reason
// (`crates/verify/ess-conformance/assets/coverage-admission.js`).
const whiteSpace =
  '[\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]';
const trimEdges = new RegExp(`^${whiteSpace}+|${whiteSpace}+$`, 'gu');

export function goTrimSpace(value: string): string {
  return value.replace(trimEdges, '');
}

/**
 * Go `strconv.Quote`, which `%q` formats with: a printable rune stays literal and everything else
 * is escaped. `JSON.stringify` escapes a different set, and the message a report quotes is the
 * same text in both runtimes or it is two texts.
 *
 * Exported because the runtime's `render` needs the same `strconv.Quote` and two copies of it
 * would be two spellings of every string a failure report prints.
 */
const printableRune = /[\p{L}\p{M}\p{N}\p{P}\p{S}]/u;
const runeEscapes: Record<string, string> = {
  '\u0007': '\\a',
  '\b': '\\b',
  '\f': '\\f',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
  '\v': '\\v',
};

/** Two texts equal code unit for code unit after mapping `A`–`Z` to `a`–`z` (beyond10x/ess#140). */
export function asciiEqualFold(left: string, right: string): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index += 1) {
    let a = left.charCodeAt(index);
    let b = right.charCodeAt(index);
    if (a >= 0x41 && a <= 0x5a) a += 0x20;
    if (b >= 0x41 && b <= 0x5a) b += 0x20;
    if (a !== b) return false;
  }
  return true;
}

export function quoteGo(value: string): string {
  let quoted = '"';
  for (const character of value) {
    if (character === '"' || character === '\\') {
      quoted += `\\${character}`;
    } else if (character === ' ' || printableRune.test(character)) {
      quoted += character;
    } else if (runeEscapes[character] !== undefined) {
      quoted += runeEscapes[character];
    } else {
      const point = character.codePointAt(0)!;
      if (point < 0x80) quoted += `\\x${point.toString(16).padStart(2, '0')}`;
      else if (point <= 0xffff) quoted += `\\u${point.toString(16).padStart(4, '0')}`;
      else quoted += `\\U${point.toString(16).padStart(8, '0')}`;
    }
  }
  return `${quoted}"`;
}

/**
 * Go `%T` for the values a decoded predicate node can still be when nothing above matched. After
 * `JSON.parse`, as after `json.Decode` into an `any`, that is a number or nothing at all.
 */
function goTypeName(node: Node | undefined): string {
  if (node === null || node === undefined) return '<nil>';
  if (typeof node === 'number') return 'float64';
  if (typeof node === 'boolean') return 'bool';
  if (typeof node === 'string') return 'string';
  return Array.isArray(node) ? '[]interface {}' : 'map[string]interface {}';
}
